/// A screen-buffer coordinate. On the wire it is the bare array
/// [row, col], in ABSOLUTE buffer coordinates — row counts from the top
/// of scrollback, not from the top of the viewport. Derive it from the
/// pane's Scroll.
class RowCol {
  const RowCol(this.row, this.col);

  final int row;
  final int col;

  /// Total: a short, long or absent array yields zeros rather than throwing.
  factory RowCol.fromJson(Object? v) {
    final a = v is List ? v : const <Object?>[];
    int at(int i) => i < a.length && a[i] is num ? (a[i] as num).toInt() : 0;
    return RowCol(at(0), at(1));
  }

  List<int> toJson() => [row, col];

  @override
  bool operator ==(Object other) =>
      other is RowCol &&
      row == other.row &&
      col == other.col;

  @override
  int get hashCode => Object.hash(row, col);

  @override
  String toString() => 'RowCol($row, $col)';
}

